    "reasoningSteps": "ഭരണഘടനാ ന്യായീകരണ ഘട്ടങ്ങൾ:",
    "art82Desc": "• ആർട്ടിക്കിൾ 82: ഹൗസ് ഓഫ് ദി പീപ്പിൾ, ഓരോ സംസ്ഥാനത്തേയും പ്രാദേശിക മണ്ഡലങ്ങളായി വിഭജിക്കുന്ന സീറ്റുകളുടെ പുനഃക്രമീകരണം.",
    "art170_2Desc": "• ആർട്ടിക്കിൾ 170(2): ഓരോ സംസ്ഥാന അസംബ്ലിയും പ്രദേശിക മണ്ഡലങ്ങളായി വിഭജിക്കപ്പെട്ടിരിക്കുന്നു, അതായത് ജനസംഖ്യ: സീറ്റ് അനുപാതം പ്രായോഗികമായി ഏകീകൃതമാണ്.",
    "art330_332Desc": "• ആർട്ടിക്കിൾ 330 & 332: പട്ടികജാതികൾക്കും പട്ടികവർഗക്കാർക്കും നിർബന്ധിത ആനുപാതിക സംവരണം.",
    "delimActSec9Desc": "• ഡീലിമിറ്റേഷൻ ആക്റ്റ് സെക്ഷൻ 9: തുല്യ ജനസംഖ്യാ വ്യതിയാനം (± 10%), ഭൗതിക സവിശേഷതകൾ, അഡ്മിനിസ്ട്രേറ്റീവ് യൂണിറ്റ് സമഗ്രത.",
    "art170Desc": "• ആർട്ടിക്കിൾ 170: ഒരു സംസ്ഥാനത്തിനുള്ളിലെ ഓരോ നിയോജക മണ്ഡലത്തിലും കർശനമായ ± 10% വ്യതിയാനത്തിനുള്ളിൽ തുല്യ ജനസംഖ്യ ഉണ്ടായിരിക്കണം.",
    "art330Desc": "• ആർട്ടിക്കിൾ 330 & 332: ഏറ്റവും പുതിയതായി പ്രസിദ്ധീകരിച്ച സെൻസസ് കണക്കുകളെ അടിസ്ഥാനമാക്കി പട്ടികജാതികൾക്കും പട്ടികവർഗക്കാർക്കും ആനുപാതിക സംവരണം.",
    "publicObjectionDesc": "• പൊതു എതിർപ്പ് വിൻഡോ: ഡീലിമിറ്റേഷൻ ആക്ടിൻ്റെ സെക്ഷൻ 9(2) പ്രകാരം, കമ്മീഷൻ കരട് അതിരുകൾ പ്രസിദ്ധീകരിക്കുകയും അന്തിമ വിജ്ഞാപനത്തിന് മുമ്പ് എതിർപ്പുകൾ സമർപ്പിക്കാൻ പൗരന്മാരെ അനുവദിക്കുകയും വേണം.",
    "contiguityDesc": "• തുടർച്ചയായ ആവശ്യകതകൾ: വീണ്ടും വരച്ച എല്ലാ നിയോജക മണ്ഡലങ്ങളും എൻക്ലേവുകളോ ഒറ്റപ്പെട്ട പോക്കറ്റുകളോ ഇല്ലാതെ ഭൂമിശാസ്ത്രപരമായി അടുത്തായിരിക്കണം.",
