    "rtiOfficialDescription": "കേന്ദ്ര പൊതു അധികാരികൾക്കായി കേന്ദ്ര പോർട്ടൽ ഉപയോഗിക്കുക. ഒരു സംസ്ഥാന അതോറിറ്റിക്ക്, ആ സംസ്ഥാനത്തിൻ്റെ വിവരാവകാശ പ്രക്രിയ പിന്തുടരുക. താഴെയുള്ള എൻട്രികൾ പോളിഗ്രാമിൽ പങ്കിട്ട കമ്മ്യൂണിറ്റി റെക്കോർഡുകളാണ്.",
    "rtiOfficialGuide": "കേന്ദ്ര വിവരാവകാശ പോർട്ടലും ഫയലിംഗ് മാർഗ്ഗനിർദ്ദേശവും",
